def find_solution(a, b, n):
    # Use the Extended Euclidean Algorithm to find the GCD of a and b
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1)
        else:
            gcd, x1, y1 = extended_gcd(y, x % y)
            return (gcd, x1 - (x // y) * y1, y1)

    # Check if the GCD of a and b is 1
    gcd, _, _ = extended_gcd(a, b)

    # If the GCD is 1, return the solution; otherwise, return None
    if gcd == 1:
        # Calculate the coefficients using the Extended Euclidean Algorithm
        x, y = extended_gcd(a, b)
        return (x % n, y % n)
    else:
        return None

