def group_tuples(tuples_list):
    # Initialize a dictionary to store the first element of each tuple
    first_elements = {}
    # Iterate through each tuple in the list
    for tuple_ in tuples_list:
        # If the tuple is not in the dictionary, add it with the first element as the key
        if tuple_[0] not in first_elements:
            first_elements[tuple_[0]] = tuple_
        # If the tuple is already in the dictionary, add the first element to the list of values
        else:
            first_elements[tuple_[0]].append(tuple_[1])
    # Return the dictionary as a list of tuples
    return list(first_elements.values())
