def find_kth(arr1, arr2, k):
    # Base case: if one array is empty, return the kth element from the other array
    if not arr1:
        return arr2[k - 1]
    if not arr2:
        return arr1[k - 1]

    # Calculate the middle indices
    mid1 = len(arr1) // 2
    mid2 = len(arr2) // 2

    # Compare the middle elements
    if arr1[mid1] < arr2[mid2]:
        # If arr1[mid1] is smaller, the kth element is in the right half of arr1
        return find_kth(arr1[mid1 + 1:], arr2, k - mid1 - 1)
    else:
