def magic_square_test(matrix):
    # Check if the matrix is a square matrix
    if len(matrix) != len(matrix[0]):
        return False

    # Calculate the sum of the first row to use as a reference
    reference_sum = sum(matrix[0])

    # Check if all rows have the same sum
    for row in matrix:
        if sum(row) != reference_sum:
            return False

    # Check if all columns have the same sum
    for col in range(len(matrix[0])):
        if sum(matrix[row][col] for row in range(len(matrix))) != reference_sum:
            return False

    # Check if the sum of the main diagonal is equal to the reference sum
    if sum(matrix[i][i] for i in range(len(matrix))) != reference_sum:
        return False

    # Check if the sum of the anti-diagonal is equal to the reference sum
    if sum(matrix[i][len(matrix) - 1 - i] for i in range(len(matrix))) != reference_sum:
        return False

    return True

