            return (x, 1, 0)
        else:
            gcd, x1, y1 = extended_gcd(y, x % y)
            return (gcd, y1, x1 - (x // y) * y1)

    # Check if n is a multiple of the GCD of a and b
    gcd, x, y = extended_gcd(a, b)
    if n % gcd != 0:
        return None

    # Scale the solution to match the value of n
    x *= n // gcd
    y *= n // gcd

    return (x, y)

